import pandas as pd
import numpy as np

# Load the datasets
DATASET_PATH = 'chunks_csv/getisord/getisord_crime_second_half_2011.csv'
ADJACENCY_PATH = 'chunks_csv/borough_adjacency.csv'

crime_data = pd.read_csv(DATASET_PATH)
adjacency_data = pd.read_csv(ADJACENCY_PATH)

# Merge the crime data with the adjacency data
merged_data = adjacency_data.merge(crime_data, on='borough', how='left')

# Create a function to calculate the combined crime rate for each borough and its neighbors
def calculate_combined_crime_rate(borough):
    neighbors = merged_data[merged_data['borough'] == borough]['neighbor'].tolist()
    combined_boroughs = [borough] + neighbors
    combined_crime_rate = merged_data[merged_data['borough'].isin(combined_boroughs)]['crime_rate_value']

    if combined_crime_rate.isnull().any():
        return None  # If any value is missing, return None

    return combined_crime_rate.sum(), combined_crime_rate.count()

# Calculate combined crime rates for all boroughs
combined_rates = {}
for borough in merged_data['borough'].unique():
    result = calculate_combined_crime_rate(borough)
    if result is not None:
        combined_rates[borough] = result

# Calculate the citywide average crime rate
citywide_average = crime_data['crime_rate_value'].mean()

# Calculate z-scores for each borough's combined crime rate
z_scores = {}
for borough, (combined_sum, count) in combined_rates.items():
    combined_average = combined_sum / count
    z_score = (combined_average - citywide_average) / (crime_data['crime_rate_value'].std() / np.sqrt(count))
    z_scores[borough] = z_score

# Identify hot and cold spots
hot_spots = {borough: z for borough, z in z_scores.items() if z > 1.96}
cold_spots = {borough: z for borough, z in z_scores.items() if z < -1.96}

# Prepare the final answer
final_results = []
for borough, z in hot_spots.items():
    final_results.append(f"{borough} (HOT, z-score = {z})")
for borough, z in cold_spots.items():
    final_results.append(f"{borough} (COLD, z-score = {z})")

if final_results:
    print(", ".join(final_results))
else:
    print("FINAL ANSWER: none")
